window.__EXPLICA={"a1-saluer":{"idea":"Para saludar en francés primero decides con quién hablas: con amigos se tutea (tu) y con profesores, desconocidos o varias personas se usa vous.","pasos":["¿Es un amigo o alguien de tu edad? → Salut ! Ça va ? / Tu t'appelles comment ?","¿Es un profesor o un desconocido? → Bonjour, Madame ! Comment allez-vous ?","Para presentarte: Je m'appelle… + Je suis… (nacionalidad, profesión) + Enchanté(e)."],"ej":[["Salut Léa ! Ça va ?","¡Hola, Léa! ¿Qué tal? (amiga)"],["Bonjour, Monsieur. Comment allez-vous ?","Buenos días, señor. ¿Cómo está usted?"],["Je m'appelle Andrés, je suis colombien.","Me llamo Andrés, soy colombiano."]],"ojo":["Salut, Madame ! Comment vas-tu ?","Bonjour, Madame ! Comment allez-vous ?","Con una profesora: saludo neutro y vous."]},"a1-nombres-age":{"idea":"La edad se dice con avoir (tener) y siempre con la palabra ans. Los números del 21 al 69 se forman como en español, con un guion o con « et un ».","pasos":["Edad: J'ai + número + ans.","21, 31, 41, 51, 61: vingt et un, trente et un…","Los demás llevan guion: vingt-deux, trente-cinq.","Para deletrear, aprende G [ʒe] y J [ʒi]: se confunden mucho."],"ej":[["J'ai dix-neuf ans.","Tengo diecinueve años."],["Vous avez quel âge ?","¿Qué edad tiene usted?"],["Comment ça s'écrit ? — J-H-O-N.","¿Cómo se escribe? — J-H-O-N."]],"ojo":["Je suis 20 ans.","J'ai 20 ans.","Como en español: «tengo» = j'ai."]},"a1-articles":{"idea":"Todo nombre francés lleva un artículo que dice si es masculino o femenino, singular o plural. El género muchas veces no es el mismo que en español.","pasos":["Definidos (el, la, los): le, la, les. Delante de vocal: l'.","Indefinidos (un, una, unos): un, une, des.","Aprende siempre el nombre con su artículo: le lait, la mer.","En plural la -s no suena: el artículo te dice si es plural."],"ej":[["le lait, la mer","la leche, el mar (¡género cambiado!)"],["l'école, l'hôpital","la escuela, el hospital"],["J'ai une sœur et deux frères.","Tengo una hermana y dos hermanos."]],"ojo":["la lait, le voiture","le lait, la voiture","No copies el género del español."]},"a1-verbes-er":{"idea":"La mayoría de los verbos franceses terminan en -er y todos se conjugan igual. Para negar se pone ne… pas alrededor del verbo.","pasos":["Quita -er: parler → parl-.","Añade: -e, -es, -e, -ons, -ez, -ent.","-e, -es y -ent no se pronuncian: je parle, ils parlent suenan igual.","Negación: ne + verbo + pas. Delante de vocal: n'."],"ej":[["J'habite à Pamplona.","Vivo en Pamplona."],["Nous étudions le français.","Estudiamos francés."],["Je n'aime pas le café.","No me gusta el café."]],"ojo":["Je ne aime pas le café.","Je n'aime pas le café.","ne → n' delante de vocal, como je → j'."]},"a1-irreguliers":{"idea":"Être (ser/estar), avoir (tener), aller (ir) y faire (hacer) son los verbos más usados y son irregulares: hay que memorizarlos.","pasos":["être: je suis, tu es, il est, nous sommes, vous êtes, ils sont.","avoir: j'ai, tu as, il a, nous avons, vous avez, ils ont.","aller: je vais… ils vont. faire: je fais… vous faites, ils font.","Muchas expresiones usan avoir donde el español usa tener: avoir faim, avoir froid."],"ej":[["J'ai faim et j'ai froid.","Tengo hambre y tengo frío."],["Il fait beau aujourd'hui.","Hace buen tiempo hoy."],["Vous faites du sport ?","¿Hace(n) deporte?"]],"ojo":["Je suis faim. / Vous faisez…","J'ai faim. / Vous faites…","ils sont [s] ≠ ils ont [z]."]},"a1-questions":{"idea":"Hay tres maneras de preguntar: subiendo la voz, con est-ce que o invirtiendo sujeto y verbo. Para preguntas abiertas se usa una palabra interrogativa.","pasos":["Sí/no: Tu viens ? · Est-ce que tu viens ? · Viens-tu ?","Palabra interrogativa: où (dónde), quand (cuándo), comment (cómo), combien (cuánto), pourquoi (por qué), qui (quién), qu'est-ce que (qué).","Responde a pourquoi con parce que."],"ej":[["Tu habites où ?","¿Dónde vives?"],["Le cours commence quand ?","¿Cuándo empieza la clase?"],["Qu'est-ce que tu fais ce soir ?","¿Qué haces esta noche?"]],"ojo":["Qu'est-ce que tu habites ?","Où est-ce que tu habites ?","Qu'est-ce que = qué; para lugares, où."]},"a1-ville":{"idea":"Para decir adónde vas o dónde está algo se usan à y de. Con le y les se unen al artículo y forman una sola palabra.","pasos":["à + le = au · à + les = aux.","de + le = du · de + les = des.","à la, à l', de la, de l' no cambian.","Lugar: à côté de, en face de, près de, loin de (con de); devant, derrière (sin de)."],"ej":[["Je vais au cinéma.","Voy al cine."],["La banque est à côté du parc.","El banco está al lado del parque."],["La poste est en face de la mairie.","El correo está frente a la alcaldía."]],"ojo":["Je vais à le cinéma.","Je vais au cinéma.","Como en español «a + el = al»."]},"a1-gouts-heure":{"idea":"Con los verbos de gusto (aimer, adorer, détester, préférer) se usa el artículo definido, igual que en español «me gusta el café». La hora se dice con Il est… heures.","pasos":["Gusto + le, la, les: J'adore la musique.","Negación: Je n'aime pas le football (se mantiene le).","Hora: Il est huit heures et quart / et demie / moins le quart.","Días en minúscula; le lundi = todos los lunes."],"ej":[["Je déteste le froid.","Odio el frío."],["Il est neuf heures et demie.","Son las nueve y media."],["Le lundi, j'ai cours à huit heures.","Los lunes tengo clase a las ocho."]],"ojo":["Je n'aime pas de football.","Je n'aime pas le football.","Con gustos, el artículo no cambia en la negación."]},"a2-passe-compose-avoir":{"idea":"El passé composé cuenta acciones terminadas. Se forma con avoir en presente + el participio. Sirve para «comí» y para «he comido».","pasos":["Conjuga avoir: j'ai, tu as, il a…","Participio: -er → -é (parlé); -ir → -i (fini).","Memoriza los irregulares: fait, pris, vu, eu, été, bu, lu, dit, écrit, mis.","Negación alrededor del auxiliar: je n'ai pas mangé."],"ej":[["Samedi, j'ai fait du sport.","El sábado hice deporte."],["Nous avons fini l'examen.","Terminamos el examen."],["Je n'ai pas vu le film.","No vi la película."]],"ojo":["J'ai prendu le bus.","J'ai pris le bus.","Los participios irregulares se aprenden de memoria."]},"a2-passe-compose-etre":{"idea":"Unos pocos verbos de movimiento o cambio (ir, venir, salir, llegar, nacer, morir…) y todos los pronominales forman el passé composé con être. El participio concuerda con el sujeto.","pasos":["¿El verbo es de la lista DR MRS VANDERTRAMP o pronominal? → être.","Conjuga être: je suis, tu es, elle est…","Concuerda el participio: elle est partie (+e), ils sont venus (+s).","Grupo de hombres y mujeres → masculino plural."],"ej":[["Je suis allée à Santa Marta.","Fui a Santa Marta. (mujer)"],["Nous sommes arrivés le soir.","Llegamos por la noche."],["Elle est née à Cúcuta.","Ella nació en Cúcuta."]],"ojo":["J'ai allé au cinéma.","Je suis allé(e) au cinéma.","aller siempre con être."]},"a2-imparfait":{"idea":"El imparfait es el imperfecto español (hablaba, comía, era). Describe cómo eran las cosas y lo que hacías siempre; el passé composé cuenta lo que pasó una vez.","pasos":["Toma la forma de nous en presente: nous parlons → parl-.","Añade: -ais, -ais, -ait, -ions, -iez, -aient.","Única excepción: être → j'étais.","Descripción o costumbre → imparfait. Acción puntual → passé composé."],"ej":[["Quand j'étais petit, j'habitais à Cali.","Cuando era pequeño, vivía en Cali."],["Il faisait beau.","Hacía buen tiempo."],["Je regardais la télé quand le téléphone a sonné.","Veía la tele cuando sonó el teléfono."]],"ojo":["Quand j'ai été petit…","Quand j'étais petit…","Para describir el pasado: imparfait."]},"a2-futur":{"idea":"Hay dos futuros: el futur proche (voy a + infinitivo) para planes cercanos y el futur simple (estudiaré) para proyectos y predicciones.","pasos":["Futur proche: aller + infinitivo, sin «à»: je vais étudier.","Futur simple: infinitivo + -ai, -as, -a, -ons, -ez, -ont: je parlerai.","Irregulares: serai, aurai, irai, ferai, pourrai, viendrai.","Después de quand, futuro: Quand je serai à Paris…"],"ej":[["Je vais étudier ce soir.","Voy a estudiar esta noche."],["L'année prochaine, j'habiterai à Lyon.","El año próximo viviré en Lyon."],["Il fera chaud demain.","Hará calor mañana."]],"ojo":["Je vais à étudier.","Je vais étudier.","Sin «à» entre aller y el infinitivo."]},"a2-pronominaux":{"idea":"Los verbos pronominales (levantarse, ducharse) llevan un pronombre que cambia con la persona. En passé composé siempre van con être.","pasos":["Pronombre según el sujeto: je me, tu te, il se, nous nous, vous vous, ils se.","Presente: je me lève, tu te douches.","Negación: je ne me lève pas.","Passé composé: être + concordancia: elle s'est levée."],"ej":[["Je me réveille à six heures.","Me despierto a las seis."],["Nous nous couchons tard.","Nos acostamos tarde."],["Elle s'est habillée vite.","Ella se vistió rápido."]],"ojo":["Je m'ai levé tard.","Je me suis levé(e) tard.","Pronominal = être."]},"a2-partitifs":{"idea":"Para una cantidad no precisa de algo (pan, agua, frutas) se usa du, de la, de l', des. En español a veces no ponemos nada: «como pan» = je mange du pain.","pasos":["Cantidad no precisa: du pain, de la viande, de l'eau, des fruits.","Negación: pas de: je ne mange pas de pain.","Cantidad precisa + de: beaucoup de, un kilo de, une bouteille de.","Gustos: artículo definido: j'adore le chocolat."],"ej":[["Je voudrais du pain et de l'eau.","Quisiera pan y agua."],["Il n'y a pas de lait.","No hay leche."],["Un kilo de tomates, s'il vous plaît.","Un kilo de tomates, por favor."]],"ojo":["Je ne mange pas du pain.","Je ne mange pas de pain.","Después de pas: de."]},"a2-comparatif":{"idea":"Para comparar se usa plus (más), moins (menos) o aussi (tan) + adjetivo + que. Bon y bien tienen formas especiales.","pasos":["Adjetivo: plus / moins / aussi + adjetivo + que.","Nombre: plus de / moins de / autant de + nombre + que.","bon → meilleur; bien → mieux.","Superlativo: le / la / les plus + adjetivo (+ de)."],"ej":[["Ce vol est moins cher.","Este vuelo es menos caro."],["Ma sœur est aussi grande que moi.","Mi hermana es tan alta como yo."],["C'est le meilleur restaurant de la ville.","Es el mejor restaurante de la ciudad."]],"ojo":["plus bon / plus bien","meilleur / mieux","Como «más bueno» → «mejor»."]},"a2-pronoms":{"idea":"Los pronombres complemento evitan repetir palabras. Se elige según lo que va después del verbo: sin preposición, con à o con de.","pasos":["Sin preposición → le, la, les (COD).","à + persona → lui, leur (COI).","Lugar o à + cosa → y. De, partitivo o cantidad → en.","El pronombre va delante del verbo."],"ej":[["Julie ? Je la connais bien.","¿Julie? La conozco bien."],["Je lui téléphone ce soir.","Lo/la llamo esta noche."],["Des frères ? J'en ai deux.","¿Hermanos? Tengo dos."]],"ojo":["Je le téléphone.","Je lui téléphone.","téléphoner à → lui."]},"a2-cod":{"idea":"El COD es la persona o cosa que recibe la acción directamente, sin preposición. Se reemplaza por le, la, l' o les y se pone delante del verbo.","pasos":["Pregunta al verbo «¿qué?» o «¿a quién?». Si no hay à ni de, es COD.","Masculino → le · femenino → la · delante de vocal → l' · plural → les.","Ponlo delante del verbo conjugado, del infinitivo o del auxiliar.","Solo el imperativo afirmativo lo lleva detrás: Prends-le !"],"ej":[["La série ? Je la regarde.","¿La serie? La veo."],["J'attends le bus → Je l'attends.","Espero el bus → Lo espero."],["Les devoirs ? Je vais les faire.","¿Las tareas? Las voy a hacer."]],"ojo":["Je vois lui. / Je vais faire le.","Je le vois. / Je vais le faire.","Nunca detrás del verbo (salvo imperativo)."]},"a2-coi":{"idea":"El COI es la persona que recibe la acción con à (hablar a alguien, escribir a alguien). Se reemplaza por lui (una persona) o leur (varias).","pasos":["¿El verbo lleva à + persona? (parler à, téléphoner à, écrire à, répondre à…)","Una persona → lui (hombre o mujer). Varias → leur (sin s).","Mismo lugar que el COD: delante del verbo o del auxiliar.","Con COI el participio no concuerda: je lui ai écrit."],"ej":[["Je parle à Julie → Je lui parle.","Hablo con Julie → Le hablo."],["Je téléphone à mes parents → Je leur téléphone.","Llamo a mis padres → Los llamo."],["Je lui ai répondu hier.","Le respondí ayer."]],"ojo":["Je la téléphone. / Je leurs écris.","Je lui téléphone. / Je leur écris.","Francés lui = español «le»."]},"a2-y":{"idea":"Y reemplaza un lugar o una cosa introducida por à. Muchas veces equivale a «allí» o no se traduce.","pasos":["¿Es un lugar (à, en, chez, dans…)? → y: j'y vais.","¿Es à + cosa (penser à, répondre à une question)? → y: j'y pense.","¿Es à + persona? → no uses y: lui / leur o à elle.","Futuro de aller: j'irai (sin y)."],"ej":[["Tu vas à la fac ? — Oui, j'y vais.","¿Vas a la u? — Sí, voy."],["Je pense à mon examen → J'y pense.","Pienso en mi examen → Pienso en eso."],["On y va ! / Vas-y !","¡Vamos! / ¡Dale!"]],"ojo":["Oui, je vais.","Oui, j'y vais.","aller necesita y."]},"a2-en":{"idea":"En reemplaza algo con de (du, de la, des) o una cantidad. Equivale a «de eso» o «algunos», y en español casi nunca se dice.","pasos":["¿Hay du, de la, des? → en: j'en mange.","¿Hay una cantidad? → en + repite la cantidad: j'en ai deux.","¿Es de + cosa o lugar (besoin de, venir de)? → en.","Con le, la, les, mon, ma… → no uses en: je le veux."],"ej":[["Tu veux du café ? — Oui, j'en veux.","¿Quieres café? — Sí, quiero."],["Des frères ? J'en ai deux.","¿Hermanos? Tengo dos."],["Non, je n'en ai pas.","No, no tengo."]],"ojo":["Oui, j'ai deux.","Oui, j'en ai deux.","La cantidad sola necesita en."]},"a2-pronoms-choisir":{"idea":"Para elegir el pronombre mira lo que viene después del verbo francés y sigue el árbol: sin preposición, à + persona, à + cosa/lugar, o de/cantidad.","pasos":["Sin preposición → le, la, les.","à + persona → lui, leur.","Lugar o à + cosa → y.","du, de la, des, cantidad o de + cosa → en."],"ej":[["Je regarde le film → Je le regarde.","Veo la película → La veo."],["Je parle à Léa → Je lui parle.","Hablo con Léa → Le hablo."],["Je bois de l'eau → J'en bois.","Tomo agua → Tomo."]],"ojo":["Je lui connais bien.","Je le connais bien.","connaître no lleva preposición → COD."]},"fon-voyelles-orales":{"idea":"El francés tiene vocales que no existen en español. La más importante es [y], la u de tu: se hace con la lengua de la «i» y los labios de la «u».","pasos":["Di «i» y, sin mover la lengua, redondea los labios como para «u»: eso es [y].","La letra u suena [y]: tu, rue, dessus.","Las letras ou suenan [u] (la «u» española): tout, vous, roue.","Practica los pares: tu / tout, rue / roue, dessus / dessous."],"ej":[["tu [ty] ≠ tout [tu]","tú ≠ todo"],["la rue [ʁy] ≠ la roue [ʁu]","la calle ≠ la rueda"],["dessus ≠ dessous","encima ≠ debajo"]],"ojo":["tu pronunciado [tu]","tu [ty]","Con la «u» española se oye tout (todo)."]},"fon-e-eu":{"idea":"El francés distingue varias «e»: cerrada [e], abierta [ɛ] y la «e» débil [ə]. Esa diferencia cambia el significado: le (singular) no suena igual que les (plural).","pasos":["é → [e] cerrada: café, été.","è, ê, ai → [ɛ] abierta: mère, fête, lait.","e sin acento al final de sílaba → [ə] débil: le, de, ce.","eu → [ø] en sílaba abierta (deux) y [œ] en sílaba cerrada (peur)."],"ej":[["le [lə] ≠ les [le]","el ≠ los"],["de [də] ≠ des [de]","de ≠ unos / de los"],["deux [dø] · peur [pœʁ]","dos · miedo"]],"ojo":["le livre pronunciado [le]","le livre [lə]","Con [le] se oye un plural."]},"fon-voyelles-nasales":{"idea":"Las vocales nasales se pronuncian dejando salir aire por la nariz, sin decir la n. En bon no se oye ninguna n.","pasos":["Si la n o la m van al final o antes de consonante, la vocal es nasal: bon, chambre.","Si después viene vocal o nn/mm, no hay nasal y la n suena: bonne, âne, une.","Distingue tres nasales: vin [ɛ̃], vent [ɑ̃], vont [ɔ̃]."],"ej":[["bon [bɔ̃] ≠ bonne [bɔn]","bueno ≠ buena"],["vin · vent · vont","vino · viento · van"],["un [œ̃] ≠ une [yn]","uno ≠ una"]],"ojo":["bon pronunciado [bon]","bon [bɔ̃]","No pronuncies la n: la vocal ya es nasal."]},"fon-consonnes":{"idea":"Algunas consonantes francesas no existen en el español de Colombia: la [z] sonora, la [ʒ], la [v] con los dientes y la r de garganta. Confundirlas cambia el significado.","pasos":["s entre vocales = [z] (zumbido): poison. ss = [s]: poisson.","v: dientes de arriba sobre el labio de abajo; b: dos labios. vol ≠ bol.","ch = [ʃ] (como «sh»); j/ge = [ʒ] (sh con voz): chat, jour.","La h no suena nunca."],"ej":[["poison [z] ≠ poisson [s]","veneno ≠ pescado"],["le vol ≠ le bol","el vuelo ≠ el tazón"],["le jour [ʒuʁ]","el día"]],"ojo":["poisson pronunciado con [z]","poisson [pwasɔ̃]","Con [z] pides veneno."]},"fon-graphies":{"idea":"En francés varias letras juntas hacen un solo sonido. Si conoces esas combinaciones, puedes leer en voz alta cualquier palabra nueva.","pasos":["ou [u] · au, eau [o] · oi [wa] · ai, ei [ɛ].","ch [ʃ] · gn [ɲ] (como la ñ) · qu [k].","ç y ge mantienen [s] y [ʒ]: garçon, mangeons.","ill suena [j]: fille, travailler (salvo ville, mille, tranquille)."],"ej":[["beau, chaud, eau","[o] en las tres"],["le roi [ʁwa]","el rey"],["la montagne [ɲ]","la montaña"]],"ojo":["fille leído [fil]","fille [fij]","[fil] es «hilo»."]},"fon-lettres-muettes":{"idea":"Muchas letras finales no se pronuncian. La -ent de los verbos (ils parlent) es muda, y la -e final hace sonar la consonante anterior.","pasos":["La consonante final casi nunca suena; las que suelen sonar: c, r, f, l (CaReFuL).","Con -e final, la consonante sí suena: petit [pəti] / petite [pətit].","-ent de verbo = muda: ils parlent [paʁl]. -ent de nombre o adverbio = [ɑ̃]: lentement.","La e débil se cae en el habla rápida: samedi → sam'di."],"ej":[["il parle = ils parlent","suenan igual"],["grand [gʁɑ̃] / grande [gʁɑ̃d]","grande (m.) / grande (f.)"],["le parc [paʁk]","el parque (la c suena)"]],"ojo":["ils parlent [paʁlɑ̃]","ils parlent [paʁl]","La -ent del verbo no suena."]},"fon-liaison":{"idea":"El francés se pronuncia por grupos unidos, sin cortes. La liaison hace sonar una consonante muda cuando la palabra siguiente empieza por vocal.","pasos":["s, x → [z]: les‿amis [lezami]. d → [t]: grand‿homme. f → [v]: neuf‿heures.","Obligatoria entre artículo y nombre, y entre pronombre y verbo: nous‿avons.","Prohibida después de et y delante de h aspirada: et | un, les | héros.","Encadenamiento: la consonante que ya suena se une a la vocal: il‿arrive."],"ej":[["les‿amis [lezami]","los amigos"],["nous‿avons [nuzavɔ̃]","tenemos"],["un‿ami [œ̃nami]","un amigo"]],"ojo":["les | amis [le ami]","les‿amis [lezami]","Sin liaison suena cortado."]},"fon-rythme-intonation":{"idea":"En francés la fuerza de voz cae siempre al final del grupo de palabras, no donde la pondrías en español. La entonación sube para seguir o preguntar y baja para terminar.","pasos":["Acento en la última sílaba pronunciada: pro-BLÈME, ca-FÉ.","En una frase, solo se acentúa el final de cada grupo: Je vais au ci-né-MA.","Pregunta sí/no: la voz sube ↗. Pregunta con où, quand…: baja ↘.","Afirmación y orden: la voz baja ↘."],"ej":[["un problème → pro-BLÈME","acento al final"],["Tu viens ? ↗","¿Vienes? (sube)"],["Où tu vas ? ↘","¿Adónde vas? (baja)"]],"ojo":["PRO-blème, CA-fé","pro-BLÈME, ca-FÉ","Acento siempre al final."]},"b11-pc-imparfait":{"idea":"Para contar una historia se combinan dos pasados: el imparfait pinta el decorado (cómo era todo) y el passé composé cuenta los hechos que hacen avanzar la historia.","pasos":["¿Describes, cuentas una costumbre o algo que estaba pasando? → imparfait.","¿Es un hecho puntual, terminado, que hace avanzar la historia? → passé composé.","Pistas: d'habitude, tous les jours → imparfait; soudain, un jour, hier → passé composé.","Acción en curso (imparfait) + quand + interrupción (passé composé)."],"ej":[["Il pleuvait quand je suis arrivé.","Llovía cuando llegué."],["D'habitude, je prenais le bus.","Normalmente tomaba el bus."],["Soudain, le téléphone a sonné.","De repente, sonó el teléfono."]],"ojo":["Quand je suis arrivé, il a plu. (si ya llovía)","Quand je suis arrivé, il pleuvait.","El decorado va en imparfait."]},"b11-plus-que-parfait":{"idea":"El plus-que-parfait es el pluscuamperfecto español (había estudiado). Sirve para una acción que pasó antes de otra acción pasada.","pasos":["Auxiliar avoir o être en imparfait: j'avais, j'étais.","+ participio: j'avais fini, j'étais parti(e).","Mismo auxiliar y misma concordancia que en el passé composé.","Úsalo para «retroceder» en un relato: déjà, parce que, la veille."],"ej":[["Le cours avait déjà commencé.","La clase ya había empezado."],["J'ai raté l'examen parce que je n'avais pas révisé.","Perdí el examen porque no había repasado."],["Elle était partie la veille.","Ella se había ido la víspera."]],"ojo":["Quand je suis arrivé, le cours a déjà commencé.","… le cours avait déjà commencé.","Lo anterior al pasado → plus-que-parfait."]},"b11-accord-participe":{"idea":"Con avoir el participio no concuerda con el sujeto. Solo concuerda con el complemento directo (COD) cuando este va antes del verbo.","pasos":["Busca el COD: ¿qué? ¿a quién?","¿Va después del verbo? → no concuerda: j'ai écrit la lettre.","¿Va antes (la, les, que, quelle)? → concuerda: la lettre que j'ai écrite.","lui, leur y en no hacen concordar."],"ej":[["La lettre ? Je l'ai écrite.","¿La carta? La escribí."],["Les photos que j'ai prises","Las fotos que tomé"],["Quelle robe as-tu mise ?","¿Qué vestido te pusiste?"]],"ojo":["La lettre que j'ai écrit.","La lettre que j'ai écrite.","COD femenino antes → -e."]},"b11-relatifs":{"idea":"Los relativos unen dos frases. Qui es sujeto, que es complemento, où indica lugar o tiempo y dont reemplaza algo con de.","pasos":["Después viene un verbo → qui: la prof qui parle.","Después viene un sujeto + verbo → que: le livre que je lis.","Lugar o momento → où: la ville où j'habite, le jour où…","Verbo con de (parler de, avoir besoin de) → dont."],"ej":[["C'est la prof qui donne le cours.","Es la profe que da la clase."],["La ville où j'ai fait mon échange","La ciudad donde hice mi intercambio"],["Le livre dont je t'ai parlé","El libro del que te hablé"]],"ojo":["Le livre que je t'ai parlé.","Le livre dont je t'ai parlé.","parler de → dont."]},"b11-gerondif":{"idea":"El gerundio francés se forma con en + -ant y dice cómo o cuándo haces algo. Siempre lleva en.","pasos":["Toma la raíz de nous: nous parlons → parl-.","Añade -ant: parlant. Irregulares: étant, ayant, sachant.","Gerundio: en + -ant: en parlant.","«Estoy haciendo» no es gerundio: je fais / je suis en train de faire."],"ej":[["J'écoute des podcasts en cuisinant.","Escucho pódcast mientras cocino."],["On progresse en parlant.","Se progresa hablando."],["Je suis en train de lire.","Estoy leyendo."]],"ojo":["Il a appris le français regardant des séries.","… en regardant des séries.","Siempre en + -ant."]},"b11-subjonctif":{"idea":"El subjuntivo aparece después de expresiones de obligación, voluntad o deseo sobre otra persona: il faut que, je veux que.","pasos":["Raíz de ils en presente: ils prennent → prenn-.","Añade -e, -es, -e, -ions, -iez, -ent.","Irregulares: sois, aie, aille, fasse, puisse, sache, veuille.","Si el sujeto es el mismo, usa infinitivo: je veux partir."],"ej":[["Il faut que tu viennes.","Es necesario que vengas."],["Mes parents veulent que je fasse un échange.","Mis padres quieren que haga un intercambio."],["Je souhaite que tu réussisses.","Deseo que tengas éxito."]],"ojo":["Il faut que tu viens.","Il faut que tu viennes.","il faut que + subjuntivo."]},"b11-conditionnel":{"idea":"El condicional (querría, podría) sirve para pedir con cortesía, expresar deseos y dar consejos.","pasos":["Raíz del futuro: parler-, ser-, aur-, pourr-.","Añade las terminaciones del imparfait: -ais, -ais, -ait, -ions, -iez, -aient.","Cortesía: je voudrais, pourriez-vous, j'aimerais.","Consejo: tu devrais…, à ta place, je…"],"ej":[["Je voudrais un café, s'il vous plaît.","Quisiera un café, por favor."],["Pourriez-vous m'aider ?","¿Podría ayudarme?"],["Tu devrais te reposer.","Deberías descansar."]],"ojo":["je voudrai (futuro) en un pedido","je voudrais","La -s final es el condicional."]},"b11-opinion":{"idea":"Para opinar se usan je pense que, à mon avis… y conectores que ordenan los argumentos. Con la negación, el verbo de opinión pide subjuntivo.","pasos":["Afirmativo + indicativo: je pense que c'est utile.","Negativo + subjuntivo: je ne pense pas que ce soit utile.","Da tu opinión: à mon avis, selon moi (nunca «dans mon opinion»).","Organiza: d'une part… d'autre part, par exemple, donc, mais."],"ej":[["À mon avis, c'est une bonne idée.","En mi opinión, es una buena idea."],["Je ne crois pas que ce soit possible.","No creo que sea posible."],["D'une part…, d'autre part…","Por una parte…, por otra…"]],"ojo":["Je ne pense pas que c'est une bonne idée.","… que ce soit une bonne idée.","Negación → subjuntivo."]},"b12-hypothese-si":{"idea":"Para las hipótesis con si hay dos esquemas fijos. Justo después de si nunca va futuro ni condicional.","pasos":["Posible: si + presente → presente, futuro o imperativo.","Imaginaria: si + imparfait → condicional.","Si + il = s'il; pero si elle, si on.","Recuerda: «si tuviera» = si j'avais (imparfait)."],"ej":[["Si tu as le temps, viens !","Si tienes tiempo, ¡ven!"],["Si j'avais le temps, je viendrais.","Si tuviera tiempo, vendría."],["S'il pleut, on restera ici.","Si llueve, nos quedaremos aquí."]],"ojo":["Si j'aurais le temps…","Si j'avais le temps…","Nunca condicional después de si."]},"b12-discours-indirect":{"idea":"El discurso indirecto sirve para contar lo que otra persona dice o pregunta. Con el verbo introductor en presente, los tiempos no cambian.","pasos":["Afirmación: il dit que…","Pregunta sí/no → si: il demande si tu viens.","qu'est-ce que → ce que; qu'est-ce qui → ce qui.","Orden → de + infinitivo: il me dit de venir."],"ej":[["Il me demande si je viens.","Me pregunta si vengo."],["Elle demande ce que tu veux.","Pregunta qué quieres."],["Le prof nous dit de lire le texte.","El profe nos dice que leamos el texto."]],"ojo":["Il me demande qu'est-ce que je veux.","Il me demande ce que je veux.","qu'est-ce que → ce que."]},"b12-pronoms-doubles":{"idea":"Cuando hay dos pronombres (la cosa y la persona), siguen un orden fijo. Y y en siempre van al final.","pasos":["me, te, nous, vous van antes de le, la, les: je te le donne.","le, la, les van antes de lui, leur: je le lui donne.","y y en van al final: je t'en donne.","Imperativo afirmativo: donne-le-moi."],"ej":[["Je te le donne.","Te lo doy."],["Je le lui ai prêté.","Se lo presté."],["Donne-le-moi !","¡Dámelo!"]],"ojo":["Je le te donne.","Je te le donne.","me/te/nous/vous primero."]},"b12-expression-temps":{"idea":"Il y a, depuis, pendant, en, dans y pour dicen cuándo o cuánto dura algo. La clave es saber si la acción terminó o sigue.","pasos":["il y a = hace (momento pasado): il y a deux jours.","depuis = desde (la acción sigue): j'attends depuis un mois.","pendant = durante; pour = duración prevista.","en = tiempo que se tarda; dans = dentro de (futuro)."],"ej":[["Je suis arrivé il y a deux jours.","Llegué hace dos días."],["J'habite ici depuis 2020.","Vivo aquí desde 2020."],["Je pars dans une semaine.","Me voy dentro de una semana."]],"ojo":["Je suis arrivé depuis deux jours.","Je suis arrivé il y a deux jours.","Acción terminada → il y a."]},"b12-cause-consequence":{"idea":"Para explicar por qué pasa algo y qué resulta se usan conectores distintos según si sigue una frase o un nombre.","pasos":["Causa + frase: parce que, car, comme (al inicio).","Causa + nombre: grâce à (positiva), à cause de (negativa).","Consecuencia: donc, alors, c'est pourquoi, si bien que.","Solo parce que responde a pourquoi ?"],"ej":[["J'ai réussi grâce à mon professeur.","Aprobé gracias a mi profesor."],["Comme il pleuvait, je suis resté.","Como llovía, me quedé."],["Il était malade, donc il n'est pas venu.","Estaba enfermo, así que no vino."]],"ojo":["J'ai réussi à cause de mon professeur.","J'ai réussi grâce à mon professeur.","Causa positiva → grâce à."]},"b12-voix-passive":{"idea":"La voz pasiva pone el resultado en primer plano: être + participio. El participio siempre concuerda con el sujeto.","pasos":["Toma el tiempo de la frase activa y ponlo en être.","Añade el participio concordado: les documents sont envoyés.","El autor, si aparece, va con par.","En el habla se prefiere on + voz activa."],"ej":[["Les documents ont été envoyés.","Los documentos fueron enviados."],["La loi a été votée par le Parlement.","La ley fue votada por el Parlamento."],["On a arrêté trois suspects.","Arrestaron a tres sospechosos."]],"ojo":["Les documents ont été envoyé.","… ont été envoyés.","El participio concuerda con el sujeto."]},"b12-possessifs-demonstratifs":{"idea":"Los pronombres posesivos (el mío) y demostrativos (el de, el que) evitan repetir un nombre.","pasos":["Posesivo según el objeto: le mien (mon livre), la mienne (ma valise).","le nôtre, le vôtre llevan acento circunflejo.","«el de» = celui de, «la de» = celle de.","«los que» = ceux qui / ceux que."],"ej":[["Ton projet est bien, mais le mien est plus écologique.","Tu proyecto está bien, pero el mío es más ecológico."],["celui de mon colocataire","el de mi compañero de piso"],["Ceux qui veulent peuvent venir.","Los que quieran pueden venir."]],"ojo":["le de mon colocataire","celui de mon colocataire","«el de» = celui de."]},"b12-courriel-argumentation":{"idea":"Un correo formal francés tiene fórmulas fijas, y un texto argumentativo sigue un plan claro con un conector al inicio de cada argumento.","pasos":["Inicio: Madame, / Monsieur, / Madame, Monsieur,","Usa vous y frases completas; nada de abreviaturas.","Plan: introducción → a favor → en contra → conclusión con tu opinión.","Cierre: Cordialement o una fórmula de cortesía completa."],"ej":[["Madame, Monsieur,","Estimados señores:"],["Tout d'abord… De plus… Cependant…","En primer lugar… Además… Sin embargo…"],["Cordialement,","Cordialmente,"]],"ojo":["Estimé monsieur, … bisous","Monsieur, … Cordialement","Usa las fórmulas francesas."]},"b21-relatifs-composes":{"idea":"Cuando el relativo va después de una preposición y se refiere a una cosa, se usa lequel (el cual) y sus formas. Es el francés escrito y formal.","pasos":["Preposición + cosa → lequel, laquelle, lesquels, lesquelles: la raison pour laquelle.","à + lequel → auquel, auxquels, auxquelles (pero à laquelle).","Locución con de (près de, au bord de) → duquel.","Persona → preposición + qui: la femme avec qui je travaille."],"ej":[["la raison pour laquelle il est parti","la razón por la cual se fue"],["le projet auquel je participe","el proyecto en el que participo"],["le lac au bord duquel on a dormi","el lago a orillas del cual dormimos"]],"ojo":["la raison pour quoi…","la raison pour laquelle…","Preposición + cosa → lequel."]},"b21-conditionnel-passe":{"idea":"El condicional pasado (habría hecho) habla de lo que no ocurrió: arrepentimientos, reproches y, en la prensa, información no confirmada.","pasos":["Forma: aurais / serais + participio: j'aurais aimé, je serais venu.","Arrepentimiento: j'aurais dû, j'aurais aimé.","Reproche: tu aurais pu m'appeler !","Hipótesis irreal: si + plus-que-parfait → condicional pasado."],"ej":[["J'aurais aimé venir.","Me habría gustado venir."],["Tu aurais dû réviser.","Deberías haber repasado."],["Si j'avais su, je ne serais pas venu.","Si hubiera sabido, no habría venido."]],"ojo":["Si j'aurais su…","Si j'avais su…","Nunca condicional después de si."]},"b21-subjonctif-passe":{"idea":"El subjuntivo pasado (que haya hecho) sirve para reaccionar a algo ya ocurrido. Además hay que saber cuándo el francés usa indicativo donde el español usa subjuntivo.","pasos":["Forma: aie / sois + participio: que tu aies réussi.","Sentimiento o duda → subjuntivo: je suis content que tu sois venu.","Certeza u opinión afirmativa → indicativo: je crois qu'il viendra.","Espérer que + indicativo (¡distinto del español!)."],"ej":[["Je suis heureux que tu aies obtenu ton diplôme.","Me alegra que hayas obtenido tu diploma."],["J'espère qu'il viendra.","Espero que venga."],["Je ne pense pas qu'il soit parti.","No creo que se haya ido."]],"ojo":["J'espère qu'il vienne.","J'espère qu'il viendra.","espérer → indicativo."]},"b21-participe-gerondif":{"idea":"Las formas en -ant tienen tres usos: participio presente (invariable, formal), gerundio (en + -ant) y adjetivo (concuerda y a veces cambia de ortografía).","pasos":["Participio presente: les candidats ayant réussi… (no cambia).","Gerundio: en + -ant, mismo sujeto: il est parti en courant.","Adjetivo verbal: concuerda: une histoire convaincante.","«Estoy trabajando» = je suis en train de travailler."],"ej":[["Il est parti en courant.","Se fue corriendo."],["Les étudiants ayant réussi l'examen…","Los estudiantes que aprobaron el examen…"],["un travail fatigant","un trabajo cansador"]],"ojo":["Je suis travaillant.","Je suis en train de travailler.","-ant nunca expresa «estoy …-ando»."]},"b21-faire-laisser":{"idea":"Faire + infinitivo significa que otra persona hace la acción por ti (hacer reparar). Laisser + infinitivo significa permitir.","pasos":["faire + infinitivo: je fais réparer ma voiture.","se faire + infinitivo: el sujeto recibe la acción: je me suis fait couper les cheveux.","laisser + infinitivo: permitir: laisse-moi parler.","Los pronombres van delante de faire: je la fais réparer."],"ej":[["Je fais réparer mon ordinateur.","Mando a reparar mi computador."],["Je me suis fait couper les cheveux.","Me corté el pelo (en la peluquería)."],["Laisse-le dormir.","Déjalo dormir."]],"ojo":["Je me suis coupé les cheveux chez le coiffeur.","Je me suis fait couper les cheveux.","Si lo hizo otro → se faire."]},"b21-modalisation":{"idea":"Modalizar es mostrar qué tan seguro estás. La certeza va con indicativo; la duda o la posibilidad, con subjuntivo.","pasos":["Certeza o probabilidad → indicativo: il est probable qu'il viendra.","Posibilidad o duda → subjuntivo: il se peut qu'il vienne.","sans doute = probablemente; sans aucun doute = sin duda.","El condicional suaviza: cela pourrait expliquer…"],"ej":[["Il viendra sans doute.","Probablemente vendrá."],["Il se peut qu'il pleuve.","Puede que llueva."],["Sans aucun doute, c'est le meilleur.","Sin ninguna duda, es el mejor."]],"ojo":["sans doute = «sin duda»","sans doute = «probablemente»","Para certeza: sans aucun doute."]},"b21-presse":{"idea":"Para entender un artículo rápido, lee primero el título y la entradilla, y aprende a leer títulos sin verbo (nominalizados).","pasos":["Lee el título y el chapeau (entradilla): resumen todo el artículo.","Título nominalizado: el verbo se vuelve nombre: augmenter → augmentation.","Selon, d'après + condicional = información no confirmada.","Distingue lo que informa (noticia) de lo que opina (editorial, columna)."],"ej":[["Hausse des loyers à Paris","Suben los arriendos en París"],["Selon la police, le suspect se serait enfui.","Según la policía, el sospechoso habría huido."],["Adoption de la loi","Se aprueba la ley"]],"ojo":["Augmentement des loyers","Augmentation des loyers","El sufijo correcto es -ation."]},"b21-debattre":{"idea":"Debatir en francés es aprobar, contradecir con cortesía y sobre todo matizar. Hay expresiones fijas que suenan naturales.","pasos":["Aprobar: vous avez raison, je suis d'accord avec vous.","Matizar: certes… mais, je vous l'accorde, il n'en reste pas moins que.","Contradecir: je ne partage pas votre avis.","Interrumpir: Excusez-moi de vous interrompre, mais…"],"ej":[["Vous avez raison, mais…","Tiene razón, pero…"],["Certes, c'est cher, mais c'est utile.","Es cierto que es caro, pero es útil."],["Je suis du même avis.","Opino lo mismo."]],"ojo":["Vous êtes raison. / Je pense le même.","Vous avez raison. / Je suis du même avis.","avoir raison, como «tener razón»."]},"genre":{"idea":"El género de un nombre francés decide el artículo, el adjetivo y el participio. Muchos nombres cambian de género respecto al español, así que hay que aprenderlos con un / une.","pasos":["Aprende cada nombre con su artículo: une méthode, une valeur.","Terminaciones femeninas: -tion, -sion, -té, -ure, -ance, -ence, -eur (abstracto).","Terminaciones masculinas: -ment, -age, -isme, -eau (ojo: la page, la plage, l'image, l'eau).","Mon / ton / son delante de vocal no cambian el género: mon amie (femenino)."],"ej":[["une méthode, une valeur","un método, un valor"],["un article intéressant","un artículo interesante"],["une équipe, la mer","un equipo, el mar"]],"ojo":["une article intéressante","un article intéressant","article es masculino."]},"accord":{"idea":"El adjetivo toma el género y el número del nombre. Muchas terminaciones cambian en femenino.","pasos":["Femenino: -if → -ive, -eux → -euse, -el → -elle, -ien → -ienne, -er → -ère.","Plural: + s; -al → -aux (solo masculino).","nouveau, beau, vieux → nouvel, bel, vieil delante de vocal.","Escrito formal: de + adjetivo plural + nombre: de nouvelles idées."],"ej":[["une étudiante sérieuse","una estudiante seria"],["des problèmes sociaux","problemas sociales"],["un nouvel ami","un nuevo amigo"]],"ojo":["des nouveaux choses","de nouvelles choses","chose es femenino."]},"pp":{"idea":"El participio pasado concuerda según el auxiliar: con être concuerda con el sujeto; con avoir, solo con el COD que va antes.","pasos":["être → concuerda con el sujeto: elle est partie.","avoir → nunca con el sujeto: elle a mangé.","avoir + COD antes (que, l', les) → concuerda con el COD.","Truco: pregunta «¿qué?». Si la respuesta está antes del verbo, concuerda."],"ej":[["Elle est arrivée hier.","Ella llegó ayer."],["Les lettres que j'ai reçues","Las cartas que recibí"],["Ils se sont levés tôt.","Se levantaron temprano."]],"ojo":["les décisions que vous avez pris","les décisions que vous avez prises","COD femenino plural antes → -es."]},"lieu":{"idea":"En español casi todo es «en»; en francés la preposición cambia según sea una ciudad o un país, y según el género del país.","pasos":["Ciudad: à / de: à Bogotá, de Paris.","País femenino (terminado en -e) o que empieza por vocal: en / de: en Colombie, en Iran.","País masculino: au / du: au Japon, au Mexique.","País plural: aux / des: aux États-Unis."],"ej":[["J'habite en Colombie.","Vivo en Colombia."],["Il travaille au Canada.","Trabaja en Canadá."],["Elle revient des États-Unis.","Ella vuelve de Estados Unidos."]],"ojo":["à Colombie","en Colombie","País femenino → en."]},"verbes":{"idea":"Muchos verbos franceses llevan una preposición fija (à o de) que hay que aprender con el verbo. El español ayuda a veces y engaña otras.","pasos":["+ à: s'opposer à, participer à, assister à, penser à (tener en mente).","+ de: dépendre de, profiter de, avoir besoin de, se souvenir de.","Contracciones: à + le = au, de + le = du.","Aprende cada verbo con su preposición en una frase."],"ej":[["Je m'oppose à ce projet.","Me opongo a este proyecto."],["Cela dépend des relations humaines.","Eso depende de las relaciones humanas."],["Nous avons besoin d'aide.","Necesitamos ayuda."]],"ojo":["dépendre à","dépendre de","Como «depender de»."]},"synt":{"idea":"Qu'est-ce que solo sirve para hacer una pregunta directa. Si la pregunta va después de otro verbo (me pregunto…, dime…), se usa ce que, ce qui o si.","pasos":["Pregunta directa: Qu'est-ce que tu veux ?","Después de un verbo: ce que (complemento): je me demande ce que tu veux.","ce qui (sujeto): dites-moi ce qui se passe.","si (sí/no): je voudrais savoir si c'est possible."],"ej":[["Je me demande ce que vous pensez.","Me pregunto qué piensa usted."],["Dites-moi ce qui ne va pas.","Dígame qué no va bien."],["Je voudrais savoir si le cours est obligatoire.","Quisiera saber si la clase es obligatoria."]],"ojo":["Je me demande qu'est-ce que vous pensez.","Je me demande ce que vous pensez.","Después de un verbo: ce que."]},"subj":{"idea":"El subjuntivo aparece con necesidad, voluntad, duda, finalidad y concesión. El español ayuda mucho porque también tiene subjuntivo, pero hay diferencias.","pasos":["il faut que, vouloir que, pour que, bien que → subjuntivo.","Certeza, opinión afirmativa, espérer → indicativo.","je pense que + indicativo; je ne pense pas que + subjuntivo.","avant que + subjuntivo; après que + indicativo."],"ej":[["Il faut que nous agissions.","Es necesario que actuemos."],["Bien qu'il soit tard, je continue.","Aunque sea tarde, sigo."],["J'espère que tu viendras.","Espero que vengas."]],"ojo":["après qu'il soit parti","après qu'il est parti","après que → indicativo."]},"cond":{"idea":"El condicional sirve para la cortesía, el consejo, la información no confirmada y las hipótesis. Nunca va justo después de si.","pasos":["Forma: raíz del futuro + -ais, -ait, -ions…","Cortesía: pourriez-vous… ? Consejo: vous devriez…","Hipótesis: si + imparfait → condicional.","Pasado irreal: si + plus-que-parfait → condicional pasado."],"ej":[["Pourriez-vous m'envoyer le dossier ?","¿Podría enviarme el expediente?"],["Si j'avais le temps, je voyagerais.","Si tuviera tiempo, viajaría."],["Le projet coûterait deux millions.","El proyecto costaría dos millones."]],"ojo":["Si j'aurais le temps…","Si j'avais le temps…","Después de si, nunca condicional."]},"consigne":{"idea":"Antes de escribir, descifra la consigna: a quién escribes, qué tareas te piden, en qué registro y con cuántas palabras. Si falta una tarea, pierdes puntos.","pasos":["Subraya el destinatario: ¿quién lee?","Subraya las tareas (a menudo dos: desacuerdo + solución).","Decide el registro: autoridad → formal y vous.","Cuenta las palabras (250 mínimo en DELF B2) y relee la consigna al final."],"ej":[["Écrivez au maire pour exprimer votre désaccord…","Escriba al alcalde para expresar su desacuerdo…"],["… et proposez une solution.","… y proponga una solución."],["250 mots minimum","250 palabras mínimo"]],"ojo":["Escribir solo el desacuerdo","Desacuerdo + solución","Cada tarea = una parte visible del texto."]},"lettre":{"idea":"La carta formal francesa tiene fórmulas fijas, en un orden fijo. Si las aprendes de memoria, ganas puntos seguros.","pasos":["Orden: remitente, destinatario, lugar y fecha, objeto, saludo, cuerpo, despedida, firma.","Saludo: título + coma: Madame la Maire,","Inicio: Je me permets de vous écrire afin de…","Despedida larga que repite el saludo: Je vous prie d'agréer, Madame la Maire, …"],"ej":[["Objet : projet de course automobile","Asunto: proyecto de carrera de autos"],["Madame la Maire,","Señora alcaldesa:"],["Je vous prie d'agréer, Madame la Maire, l'expression de mes salutations distinguées.","Atentamente, (fórmula formal)"]],"ojo":["Bonjour Madame… Cordialement !","Madame la Maire, … Je vous prie d'agréer…","Nada de «Bonjour» ni signos de exclamación."]},"registre":{"idea":"En un texto formal, cada palabra familiar baja la nota. Hay equivalencias fijas entre lo familiar y lo formal.","pasos":["ça → cela; on → nous; les gens → les habitants.","très → extrêmement; plein de → de nombreux; boulot → travail.","Negación completa: ne… pas (nunca solo pas).","Cambia il y a y faire por verbos precisos."],"ej":[["Cela pose un problème.","Eso plantea un problema."],["De nombreux habitants sont inquiets.","Numerosos habitantes están preocupados."],["Nous ne pouvons pas accepter ce projet.","No podemos aceptar este proyecto."]],"ojo":["ça va causer plein de problèmes","cela provoquera de nombreux problèmes","Registro formal en todo el texto."]},"conn":{"idea":"Los conectores son las señales del texto: dicen si añades, opones, concedes o concluyes. Primero decide la relación lógica y después el conector.","pasos":["Añadir: de plus, en outre. Oponer: cependant, en revanche.","Conceder: certes… mais; bien que + subjuntivo; même si + indicativo.","Varía: no repitas el mismo conector en un párrafo.","Coma después del conector al inicio de frase; termina con en définitive."],"ej":[["Certes, le projet est ambitieux, mais il est coûteux.","Es cierto que el proyecto es ambicioso, pero es costoso."],["De plus, il pollue.","Además, contamina."],["En définitive, il faut y renoncer.","En definitiva, hay que renunciar a él."]],"ojo":["Mais… mais… mais…","Cependant… En revanche… Toutefois…","Varía los conectores."]},"rep":{"idea":"En francés escrito repetir la misma palabra se considera un error de estilo. Se evita con pronombres, sinónimos y palabras más precisas.","pasos":["Pronombres: le, la, les; lui, leur; y; en.","Reemplaza palabras vagas: dire, faire, chose, problème.","Retoma un nombre con ce / cette + sinónimo: ce projet → cette initiative.","Una sola marca de opinión por frase."],"ej":[["Le projet est coûteux. Cette initiative est aussi polluante.","El proyecto es costoso. Esta iniciativa también contamina."],["Le document indique que…","El documento indica que…"],["À mon avis, c'est utile.","En mi opinión, es útil."]],"ojo":["À mon avis, je crois que…","À mon avis, …","Una sola marca de opinión."]},"ortho":{"idea":"Las faltas de ortografía cuestan puntos. Muchas vienen del inglés o del español, y otras de homófonos (a/à, ou/où).","pasos":["Aprende de memoria: entreprise, adresse, développement, exemple, environnement.","a = verbo (se puede decir avait); à = preposición.","où = lugar o tiempo; ou = o.","-er si puedes decir prendre; -é si puedes decir pris."],"ej":[["Il a une adresse à Paris.","Tiene una dirección en París."],["Tu viens ou tu restes ?","¿Vienes o te quedas?"],["Il faut manger / J'ai mangé.","Hay que comer / Comí."]],"ojo":["enterprises, adresses (con dd)","entreprises, adresses","Cuidado con el inglés."]},"ponct":{"idea":"La puntuación francesa tiene reglas de espacio propias: los signos dobles llevan espacio antes. Y nunca se pone coma entre sujeto y verbo.","pasos":["Signos dobles ; : ? ! → espacio antes.","Signos simples . , → sin espacio antes.","Nunca coma entre sujeto y verbo.","Días, meses e idiomas en minúscula; comillas « … »."],"ej":[["Pourquoi ? Parce que c'est important !","¿Por qué? ¡Porque es importante!"],["le lundi 3 septembre","el lunes 3 de septiembre"],["Il a dit : « Je viens. »","Dijo: «Vengo»."]],"ojo":["Pourquoi? / Les habitants, sont inquiets.","Pourquoi ? / Les habitants sont inquiets.","Espacio antes de ? y sin coma sujeto-verbo."]},"p-lettre":{"idea":"Proyecto guiado: escribes paso a paso una carta al alcalde contra una carrera de autos en el centro, cuidando el registro y los errores más frecuentes.","pasos":["Identifica las dos tareas: desacuerdo + solución.","Usa las fórmulas de la carta formal.","Mantén el registro formal y vous de principio a fin.","Relee con la lista de errores: acentos, concordancias, conectores."],"ej":[["Je me permets de vous écrire afin de vous faire part de mon désaccord.","Me permito escribirle para expresarle mi desacuerdo."],["Je vous propose plutôt d'organiser…","Le propongo más bien organizar…"],["Dans l'attente de votre réponse, …","A la espera de su respuesta, …"]],"ojo":["Bonjour Monsieur le Maire !","Monsieur le Maire,","Registro formal desde el saludo."]},"plan":{"idea":"En el oral del DELF o DALF el jurado evalúa la estructura: presentar el documento, plantear una pregunta, desarrollar con orden y concluir.","pasos":["Presenta el documento (tipo, fuente, tema).","Plantea la problemática: una pregunta clara.","Analiza y da tu opinión con ejemplos.","Concluye: síntesis, respuesta y apertura."],"ej":[["Le document proposé aborde la question de…","El documento propuesto trata la cuestión de…"],["On peut se demander si…","Cabe preguntarse si…"],["Dans un premier temps…, dans un second temps…","En primer lugar…, en segundo lugar…"]],"ojo":["Terminar con «voilà, c'est tout»","En définitive, … Reste à savoir si…","La conclusión se prepara antes."]},"concl":{"idea":"Una buena conclusión tiene tres gestos: anuncia el final, responde a la pregunta con matices y abre una nueva pregunta. Nunca trae argumentos nuevos.","pasos":["Anuncia: en définitive, en conclusion.","Responde con matiz: oui, mais…, à condition de…","Abre: Reste à savoir si…, On peut dès lors se demander si…","Tres a cinco frases."],"ej":[["En définitive, le télétravail présente des avantages…","En definitiva, el teletrabajo tiene ventajas…"],["… à condition d'être encadré.","… siempre que esté regulado."],["Reste à savoir si les entreprises suivront.","Queda por saber si las empresas lo seguirán."]],"ojo":["Un argumento nuevo al final","Síntesis + respuesta + apertura","La conclusión no añade ideas."]},"oral":{"idea":"En el examen oral siempre se trata de usted al examinador y se usan fórmulas para pedir la palabra, pedir que repita o matizar.","pasos":["Siempre vous con el examinador.","Cortesía: pourriez-vous répéter ?","Tomar la palabra: permettez-moi de…","Desacuerdo educado: je comprends votre point de vue ; cependant…"],"ej":[["Pourriez-vous répéter la question ?","¿Podría repetir la pregunta?"],["Permettez-moi d'ajouter un exemple.","Permítame añadir un ejemplo."],["Je ne suis pas tout à fait d'accord.","No estoy del todo de acuerdo."]],"ojo":["Tu peux répéter ?","Pourriez-vous répéter ?","En el examen: vous."]},"phono":{"idea":"Al leer en voz alta hay que callar las letras mudas (como -ent de los verbos) y hacer las liaisons obligatorias.","pasos":["-ent de verbo (ils parlent) = mudo.","-ent de nombre o adverbio = [ɑ̃]: le moment.","Liaison obligatoria: les‿enfants, nous‿avons, ils‿ont [z].","Prohibida después de et y delante de h aspirada."],"ej":[["ils expérimentent [ɛkspeʁimɑ̃t]","la -ent final no suena"],["ils‿ont [ilzɔ̃] ≠ ils sont [ilsɔ̃]","tienen ≠ son"],["les‿enfants [lezɑ̃fɑ̃]","los niños"]],"ojo":["ils parlent [paʁlɑ̃]","ils parlent [paʁl]","-ent verbal no se pronuncia."]},"nombres":{"idea":"Del 70 al 99 los números franceses se forman sumando y multiplicando. Escucha el número completo antes de escribirlo.","pasos":["70 = soixante-dix (60 + 10); 71 = soixante et onze.","80 = quatre-vingts (4 × 20); 81 = quatre-vingt-un.","90 = quatre-vingt-dix; 99 = quatre-vingt-dix-neuf.","Decimales con virgule: 3,5 = trois virgule cinq; % = pour cent."],"ej":[["soixante-dix-sept","77"],["quatre-vingt-quinze","95"],["mille neuf cent quatre-vingt-dix","1990"]],"ojo":["Escribir 60 al oír soixante-dix…","Esperar el final: 70","Nunca escribas antes de oír todo el número."]},"dates":{"idea":"Fechas, horas y porcentajes son puntos fáciles en la comprensión oral si los anotas en cifras mientras escuchas.","pasos":["Fecha sin «de»: le mercredi 3 septembre.","Hora: onze heures dix = 11 h 10; midi et demi = 12 h 30.","Proporciones: un sur trois, plus de la moitié, trente pour cent.","Anota siempre en cifras durante la escucha."],"ej":[["le mercredi trois septembre","el miércoles 3 de septiembre"],["à quatorze heures quinze","a las 14:15"],["un étudiant sur trois","uno de cada tres estudiantes"]],"ojo":["le trois de septembre","le trois septembre","Sin «de» en la fecha."]},"p-expose":{"idea":"Proyecto guiado: preparas un exposé oral del DELF B2 a partir de un barómetro sobre la felicidad en el trabajo, desde la escucha hasta la conclusión.","pasos":["Anota las cifras en números mientras escuchas.","Presenta el documento y plantea la pregunta.","Analiza y matiza las cifras (toutefois, néanmoins).","Da tu opinión con un ejemplo de Colombia y concluye."],"ej":[["Selon ce baromètre, 69 % des salariés se disent heureux.","Según este barómetro, el 69 % de los asalariados se dicen felices."],["Il n'en demeure pas moins que le stress touche 30 % d'entre eux.","No es menos cierto que el estrés afecta al 30 %."],["En Colombie, par exemple, …","En Colombia, por ejemplo, …"]],"ojo":["Le document, il parle de…","Le document aborde…","Sin repetir el sujeto con un pronombre."]},"inv":{"idea":"La inversión pone el verbo antes del sujeto. Suena formal y es típica del francés escrito y de los exámenes C1.","pasos":["Sujeto pronombre: verbo-pronombre: Pouvez-vous… ?","Sujeto nombre: nombre + verbo-pronombre: Le maire a-t-il répondu ?","Entre dos vocales se añade -t-: a-t-il, va-t-elle.","Después de peut-être, sans doute, à peine al inicio: Peut-être faut-il…"],"ej":[["Le maire a-t-il répondu ?","¿Ha respondido el alcalde?"],["Peut-être faut-il revoir le projet.","Quizá haya que revisar el proyecto."],["« C'est inquiétant », affirme la sociologue.","«Es preocupante», afirma la socióloga."]],"ojo":["A-il répondu ?","A-t-il répondu ?","-t- entre dos vocales."]},"ordre":{"idea":"En francés el orden de las palabras es más rígido que en español: el adjetivo suele ir después del nombre y los pronombres tienen un orden fijo.","pasos":["Adjetivo después del nombre, salvo los cortos: beau, grand, jeune, vieux, nouveau.","Algunos cambian de sentido: un grand homme (gran hombre) ≠ un homme grand (alto).","Orden de pronombres: me/te/se → le/la/les → lui/leur → y → en.","La negación encierra el bloque: je ne le lui ai pas envoyé."],"ej":[["une analyse politique précise","un análisis político preciso"],["mon ancien professeur","mi antiguo profesor (ya no lo es)"],["Je ne le lui ai pas envoyé.","No se lo envié."]],"ojo":["une politique analyse","une analyse politique","Adjetivo de relación pegado al nombre, después."]},"phrase":{"idea":"Un texto C1 alterna frases simples y complejas. La clave de la frase compleja es elegir bien el relativo según la construcción del verbo.","pasos":["Frase simple = un verbo conjugado.","Relativo según el verbo: qui (sujeto), que (COD), dont (de), où (lugar/tiempo).","Preposición + cosa → lequel.","Más de 30-35 palabras: corta la frase."],"ej":[["L'étude dont parle l'article","El estudio del que habla el artículo"],["Le pays où je suis né","El país donde nací"],["Il est absent, car il est malade.","Está ausente, pues está enfermo."]],"ojo":["Car il est malade, il est absent.","Il est absent, car il est malade.","car nunca al inicio."]},"into":{"idea":"La melodía de la voz dice si afirmas, preguntas o enumeras. Una voz que baja significa «terminé mi idea».","pasos":["Afirmación ↘.","Pregunta sin palabra interrogativa ↗: Vous venez ?","Pregunta con palabra interrogativa, a menudo ↘: Où allez-vous ?","Enumeración: ↗ en cada elemento, ↘ en el último."],"ej":[["Vous avez lu le document ? ↗","¿Leyó el documento?"],["Vous avez lu le document. ↘","Leyó el documento."],["le salaire ↗, les horaires ↗ et le stress ↘","el salario, los horarios y el estrés"]],"ojo":["Acento en cada palabra","Acento al final del grupo","Solo la última sílaba del grupo."]},"gnexp":{"idea":"El grupo nominal es un nombre con todo lo que lo acompaña. Enriquecerlo permite decir mucho en pocas palabras, algo muy valorado en el resumen y la síntesis.","pasos":["GN = determinante + nombre núcleo + expansiones.","Expansiones: adjetivo, complemento del nombre (de + nombre), relativa.","Se pueden acumular: une étude récente sur le travail qui…","Una relativa con être se reduce: qui est située → située."],"ej":[["une maison ancienne entourée d'arbres","una casa antigua rodeada de árboles"],["la hausse rapide des loyers","el alza rápida de los arriendos"],["un projet ambitieux qui divise","un proyecto ambicioso que divide"]],"ojo":["une maison qui est entourée d'arbres","une maison entourée d'arbres","Reduce la relativa con être."]},"advment":{"idea":"La mayoría de los adverbios en -ment (como -mente) se forman sobre el femenino del adjetivo. Hay terminaciones especiales que se escriben con dos m.","pasos":["Regla general: femenino + -ment: lente → lentement.","Si el masculino termina en vocal: vrai → vraiment.","-ant → -amment; -ent → -emment (ambos suenan [amɑ̃]).","Memoriza: énormément, précisément, gentiment, brièvement."],"ej":[["évident → évidemment","evidente → evidentemente"],["constant → constamment","constante → constantemente"],["précis → précisément","preciso → precisamente"]],"ojo":["évidement","évidemment","-ent → -emment."]},"advplace":{"idea":"El adverbio nunca va entre el sujeto y el verbo, algo que en español sí hacemos («él siempre llega tarde»).","pasos":["Tiempo simple: después del verbo: il arrive toujours en retard.","Tiempo compuesto: adverbio corto entre auxiliar y participio: j'ai déjà fini.","Adverbio en -ment: después del participio.","Hier, demain, ici: al inicio o al final de la frase."],"ej":[["Il arrive toujours en retard.","Siempre llega tarde."],["J'ai bien compris.","Entendí bien."],["Je n'ai pas encore fini.","Todavía no he terminado."]],"ojo":["Il toujours arrive en retard.","Il arrive toujours en retard.","Nunca entre sujeto y verbo."]},"pronoms":{"idea":"Los pronombres complemento van delante del verbo, del auxiliar o del infinitivo, y cuando hay dos siguen un orden fijo.","pasos":["Delante del verbo: je le vois; je lui ai parlé; je vais le faire.","Orden: me/te/se/nous/vous → le/la/les → lui/leur → y → en.","Imperativo afirmativo: detrás: donne-le-lui, vas-y.","La negación rodea el bloque: je ne le lui ai pas dit."],"ej":[["Je le lui ai envoyé.","Se lo envié."],["Donne-la-moi.","Dámela."],["Il ne m'en a pas parlé.","No me habló de eso."]],"ojo":["Je lui le donne.","Je le lui donne.","le/la/les antes de lui/leur."]},"compl":{"idea":"Saber si un verbo lleva complemento con o sin preposición te permite elegir bien el pronombre (le o lui) y el relativo (que o dont).","pasos":["COD: sin preposición: je regarde le film.","COI: con preposición (à, de): je parle à Marie, je parle de ce film.","El atributo va después de être, sembler, devenir y describe al sujeto.","Un verbo puede cambiar de construcción según su sentido."],"ej":[["Je pense à mon examen (COI).","Pienso en mi examen."],["Elle semble fatiguée (atributo).","Parece cansada."],["Je joue au football / du piano.","Juego fútbol / toco piano."]],"ojo":["le film que je t'ai parlé","le film dont je t'ai parlé","parler de → dont."]},"relief":{"idea":"La puesta de relieve destaca la idea importante: C'est… qui, C'est… que, Ce qui…, c'est…","pasos":["Sujeto destacado: C'est… qui: C'est le prix qui pose problème.","Otro elemento: C'est… que: C'est en 2020 que tout a changé.","Al inicio: Ce qui (sujeto) / Ce que (COD) / Ce dont (de)…, c'est…","Úsala una o dos veces por párrafo, no más."],"ej":[["Ce qui m'inquiète, c'est l'isolement.","Lo que me preocupa es el aislamiento."],["C'est vous qui avez raison.","Es usted quien tiene razón."],["Ce dont nous avons besoin, c'est de temps.","Lo que necesitamos es tiempo."]],"ojo":["C'est moi qui a raison.","C'est moi qui ai raison.","El verbo concuerda con lo destacado."]},"passif":{"idea":"El texto académico evita je y on: prefiere construcciones impersonales y la voz pasiva para sonar objetivo.","pasos":["Impersonal: il est + adjetivo + de + infinitivo: il est nécessaire d'agir.","il est + adjetivo + que + subjuntivo: il est important que…","il semble que + subjuntivo; il apparaît que + indicativo.","Pasiva: être + participio concordado (+ par)."],"ej":[["Il est essentiel de réduire les coûts.","Es esencial reducir los costos."],["Il semble que la situation soit stable.","Parece que la situación es estable."],["Une enquête a été menée.","Se realizó una encuesta."]],"ojo":["Je pense qu'il faut… (en un informe)","Il convient de…","Impersonal en el texto académico."]},"ponct2":{"idea":"En C1 la puntuación organiza las ideas y puede cambiar el sentido. Una coma puede transformar una relativa.","pasos":["Relativa entre comas = explicativa (todos); sin comas = especificativa (algunos).","Dos puntos: explicación, enumeración o cita.","Punto y coma: dos ideas paralelas.","Nunca coma entre sujeto y verbo ni antes de que."],"ej":[["Les étudiants, qui étaient fatigués, sont partis.","Los estudiantes (todos) estaban cansados y se fueron."],["Les étudiants qui étaient fatigués sont partis.","Solo los cansados se fueron."],["Deux options s'offrent à nous : agir ou attendre.","Tenemos dos opciones: actuar o esperar."]],"ojo":["Il pense, que c'est utile.","Il pense que c'est utile.","Sin coma antes de que."]},"p-gn":{"idea":"Proyecto guiado: escribes una descripción corta enriqueciendo los grupos nominales con adjetivos, complementos, participios y relativas.","pasos":["Elige qué describir: persona, lugar u objeto.","Enriquece cada nombre con 2 o 3 expansiones variadas.","Adjetivos cortos antes del nombre; color, forma y participios después.","Revisa las concordancias antes de entregar."],"ej":[["une vieille maison blanche aux volets bleus","una vieja casa blanca de postigos azules"],["un homme grand, vêtu d'un long manteau","un hombre alto, vestido con un abrigo largo"],["la mer immense qui brille au soleil","el mar inmenso que brilla al sol"]],"ojo":["une maison qui est blanche et qui est vieille","une vieille maison blanche","Condensa en el grupo nominal."]},"reform":{"idea":"Reformular es decir la misma idea con otras palabras y otra estructura. En el resumen y la síntesis está prohibido copiar el texto.","pasos":["Nominaliza: les prix augmentent → la hausse des prix.","Usa sinónimos y palabras generales.","Cambia la estructura: activa → pasiva.","Conserva solo los términos técnicos."],"ej":[["Les loyers augmentent fortement.","→ la forte hausse des loyers"],["c'est-à-dire, autrement dit","es decir, dicho de otro modo"],["Le gouvernement a adopté la loi. → La loi a été adoptée.","Cambio a la pasiva"]],"ojo":["Copiar una frase del texto","Misma idea, otras palabras","Nunca recopies el texto fuente."]},"argu":{"idea":"Un texto argumentativo defiende una tesis con argumentos y ejemplos. Cada párrafo desarrolla un solo argumento.","pasos":["Tesis clara al principio.","Un párrafo = idea directriz + explicación + ejemplo + mini conclusión.","Varía los argumentos: autoridad, ejemplo, lógica, analogía.","Matiza: certes…, mais…; il n'en reste pas moins que…"],"ej":[["Certes, le télétravail isole ; il n'en reste pas moins qu'il fait gagner du temps.","Es cierto que aísla; no deja de ser verdad que ahorra tiempo."],["Prenons l'exemple de…","Tomemos el ejemplo de…"],["Force est de constater que…","Hay que reconocer que…"]],"ojo":["Tres argumentos en un párrafo","Un argumento por párrafo","El corrector evalúa el razonamiento."]},"reprise":{"idea":"Un texto cohesionado retoma lo que ya dijo sin repetirlo: con pronombres, sinónimos, términos generales o nombres que resumen.","pasos":["Pronombres: le, la, en, y.","Sinónimo o término general: le télétravail → cette pratique.","Nombre que resume una frase: cette hausse, ce phénomène.","celui-ci / ce dernier = el último nombrado."],"ej":[["Les loyers ont augmenté de 10 %. Cette hausse inquiète.","Los arriendos subieron un 10 %. Esta alza preocupa."],["Paul et Marc sont venus ; ce dernier était fatigué.","Paul y Marc vinieron; este último estaba cansado."],["Le télétravail… cette pratique…","El teletrabajo… esta práctica…"]],"ojo":["le télétravail… le télétravail… le télétravail","le télétravail… cette pratique… celle-ci","Varía la forma de retomar."]},"rapport":{"idea":"El discurso referido cuenta lo que dijo otro. Si el verbo introductor está en pasado, los tiempos cambian (concordancia de tiempos).","pasos":["presente → imparfait; passé composé → plus-que-parfait; futuro → condicional.","Imperativo → de + infinitivo.","Preguntas: si, ce que, ce qui, sin inversión.","demain → le lendemain; hier → la veille."],"ej":[["Il a dit qu'il viendrait.","Dijo que vendría."],["Elle a demandé si c'était possible.","Preguntó si era posible."],["L'auteur souligne que…","El autor subraya que…"]],"ojo":["Il a dit qu'il viendra demain.","Il a dit qu'il viendrait le lendemain.","Concordancia de tiempos en pasado."]},"cause":{"idea":"Para explicar causas y consecuencias en C1 se usan herramientas variadas que añaden matices: causa positiva, negativa, conocida o dudosa.","pasos":["Causa + nombre: grâce à (+), à cause de (−), en raison de (neutra), faute de (falta).","Causa + verbo: parce que, puisque (conocida), étant donné que, sous prétexte que (dudosa).","Consecuencia: donc, par conséquent, si bien que, au point que; d'où + nombre.","Causa y consecuencia → indicativo."],"ej":[["En raison de la grève, le cours est annulé.","Debido a la huelga, se cancela la clase."],["Faute de temps, il n'a pas fini.","Por falta de tiempo, no terminó."],["Il a plu, si bien que le match a été reporté.","Llovió, de modo que se aplazó el partido."]],"ojo":["grâce à la grève (causa negativa)","à cause de la grève / en raison de la grève","grâce à solo para lo positivo."]},"conces":{"idea":"La oposición contrasta dos hechos; la concesión reconoce algo que no impide lo otro. Cada conector exige un modo distinto.","pasos":["Oposición: alors que, tandis que + indicativo; en revanche.","Concesión: bien que, quoique + subjuntivo; même si + indicativo.","malgré, en dépit de + nombre.","avoir beau + infinitivo: J'ai beau travailler, …"],"ej":[["Bien qu'il soit fatigué, il continue.","Aunque está cansado, sigue."],["Même s'il pleut, je sors.","Aunque llueva, salgo."],["Malgré la pluie, le match a eu lieu.","A pesar de la lluvia, hubo partido."]],"ojo":["malgré que + frase","bien que + subjuntivo / malgré + nombre","Nunca «malgré que»."]},"but":{"idea":"Finalidad, condición e hipótesis sirven para proponer soluciones e imaginar escenarios. Cada una pide un modo verbal.","pasos":["Finalidad: pour que, afin que + subjuntivo; mismo sujeto → pour, afin de + infinitivo.","Condición: à condition que, pourvu que, à moins que + subjuntivo.","au cas où + condicional; en cas de + nombre.","Hipótesis: si + imparfait → condicional."],"ej":[["Il faut agir afin que chacun soit protégé.","Hay que actuar para que todos estén protegidos."],["Je viendrai à condition que tu m'invites.","Vendré a condición de que me invites."],["Au cas où il pleuvrait, on resterait ici.","En caso de que lloviera, nos quedaríamos."]],"ojo":["pour que + indicativo","pour que + subjuntivo","Finalidad → subjuntivo."]},"plans":{"idea":"El plan depende del tipo de pregunta. Elegir el plan correcto es responder de verdad a lo que se pregunta.","pasos":["Pregunta cerrada (sí/no) → plan dialéctico: tesis, antítesis, síntesis.","Un fenómeno → plan analítico: causas, consecuencias, soluciones.","Pregunta abierta o síntesis → plan temático.","Introducción: gancho, tema, problemática, anuncio del plan."],"ej":[["Faut-il interdire… ? → plan dialectique","¿Hay que prohibir…? → plan dialéctico"],["Le télétravail : causes, effets, solutions","Plan analítico"],["Dans un premier temps…, puis…","En primer lugar…, luego…"]],"ojo":["Resumir doc. 1 y luego doc. 2","Plan temático que cruza los documentos","En la síntesis, idea por idea."]},"notes":{"idea":"Se habla tres veces más rápido de lo que se escribe: tomar apuntes es elegir lo esencial y abreviarlo.","pasos":["Anota ideas, no frases.","Prioriza palabras clave, cifras, fechas, nombres y relaciones lógicas.","Usa siempre los mismos símbolos: ↗ aumento, → consecuencia, ≠ oposición.","Cifras en números y deja margen para completar."],"ej":[["télétr. ↗ depuis 2020","el teletrabajo aumenta desde 2020"],["stress → 30 % sal.","estrés: 30 % de los asalariados"],["IA ≠ interdire","IA: no prohibir"]],"ojo":["Escribir todo lo que se dice","Palabras clave + símbolos","Selecciona y abrevia."]},"resume":{"idea":"El resumen reduce un texto a un cuarto o un tercio, en el mismo orden y desde el punto de vista del autor, pero sin nombrarlo ni opinar.","pasos":["Busca la tesis y la idea de cada párrafo.","Suprime ejemplos, enumeraciones y preguntas retóricas.","Reformula con tus palabras y conserva los conectores lógicos.","Respeta el número de palabras (± 10 %)."],"ej":[["pas de « je », pas d'opinion","sin «yo» ni opinión"],["Il faut former les étudiants à l'IA plutôt que l'interdire.","Hay que formar en IA en lugar de prohibirla."],["70 mots ± 10 %","entre 63 y 77 palabras"]],"ojo":["L'auteur pense que…","(la idea directamente)","En el resumen no se nombra al autor."]},"cr":{"idea":"La reseña (compte rendu) presenta un documento y expone el pensamiento de su autor, con verbos introductores precisos.","pasos":["Presenta el documento: autor, fuente, fecha, tema.","Tercera persona, presente, tono objetivo.","Puedes reorganizar las ideas.","Varía los verbos: affirmer, souligner, rappeler, déplorer."],"ej":[["Dans cet article paru dans Le Monde, la sociologue X analyse…","En este artículo publicado en Le Monde, la socióloga X analiza…"],["Elle souligne que…","Subraya que…"],["L'auteur déplore…","El autor lamenta…"]],"ojo":["Il dit que… il dit que…","Il affirme… il souligne… il rappelle…","Un verbo preciso para cada intención."]},"acad":{"idea":"El registro académico es objetivo, preciso y matizado. Las palabras familiares bajan la nota aunque las ideas sean buenas.","pasos":["«nous» de autor o impersonal en vez de «je».","Verbos precisos: mettre en évidence, constituer, s'avérer.","Nada de palabras vagas (truc, chose) ni generalizaciones.","Matiza: dans une certaine mesure, en partie, semble-t-il."],"ej":[["Cette étude met en évidence…","Este estudio pone de relieve…"],["Nous verrons dans un premier temps…","Veremos en primer lugar…"],["dans une certaine mesure","en cierta medida"]],"ojo":["C'est super important, tout le monde le sait.","Il s'agit d'un enjeu majeur.","Nada de oral familiar."]},"citer":{"idea":"En la universidad toda idea ajena debe llevar su fuente. Citar es copiar entre comillas; parafrasear es reformular, también con fuente.","pasos":["Cita: « … » + fuente.","Paráfrasis: reformulación + fuente, sin comillas.","[…] para un corte; [palabra] para un añadido.","Referencia: (Autor, año, p. X)."],"ej":[["Selon Dupont (2020, p. 12), « … ».","Según Dupont (2020, p. 12), «…»."],["Comme le montre Dupont (2020), …","Como muestra Dupont (2020), …"],["« Le travail […] reste central. »","Cita con corte"]],"ojo":["Copiar sin comillas ni fuente","Comillas + fuente, o paráfrasis + fuente","Eso es plagio."]},"synth":{"idea":"La síntesis del DALF C1 cruza varios documentos en unas 220 palabras: compara lo que dicen, sin opinar ni copiar.","pasos":["Título + introducción (tema y problemática).","Plan temático: convergencias y divergencias, idea por idea.","Conectores de confrontación: si le premier…, le second…","Nada de opinión, información externa ni citas copiadas."],"ej":[["Les deux auteurs s'accordent à dire que…","Ambos autores coinciden en que…"],["Contrairement au premier document, le second…","A diferencia del primer documento, el segundo…"],["alors que, tandis que, en revanche","mientras que, en cambio"]],"ojo":["Doc. 1 dit… Doc. 2 dit…","Les deux auteurs s'accordent… mais divergent sur…","Confronta, no resumas por separado."]},"essai":{"idea":"El ensayo argumentativo del DALF C1 pide tu voz: una posición clara y matizada, defendida con argumentos y ejemplos, en la forma que pide la consigna.","pasos":["Identifica la forma pedida (artículo, carta…) y el mínimo de palabras (250).","Tesis clara y matizada.","Introducción, desarrollo en 2 o 3 partes, conclusión.","Cada párrafo empieza por su idea directriz."],"ej":[["Dans quelle mesure… ?","¿En qué medida…?"],["Tout d'abord… Ensuite… Enfin…","En primer lugar… Luego… Por último…"],["En définitive, … Reste à savoir si…","En definitiva… Queda por saber si…"]],"ojo":["Sin título en un artículo","Artículo con título","La forma también se evalúa."]},"oralc1":{"idea":"El oral del DALF C1: una hora de preparación con documentos, un exposé de 8 a 10 minutos y un debate con el jurado.","pasos":["Prepara con palabras clave y un plan, no un texto completo.","Transiciones explícitas: passons maintenant à…","Da tu punto de vista apoyado en los documentos.","En el debate: vous, reformular, conceder y defender."],"ej":[["Passons maintenant à la deuxième partie.","Pasemos ahora a la segunda parte."],["Si je vous ai bien compris, …","Si le entendí bien, …"],["Je vous accorde que…, néanmoins…","Le concedo que…, no obstante…"]],"ojo":["Leer un texto redactado","Hablar a partir de palabras clave","El jurado evalúa la interacción."]},"p-synth":{"idea":"Proyecto guiado: preparas una síntesis de dos documentos opuestos sobre el teletrabajo, paso a paso. El texto está en el botón «Texte de la leçon» de cada ejercicio.","pasos":["Lee los dos documentos y formula el tema común.","Busca las convergencias y la divergencia principal.","Propón un título y una problemática que muestren la tensión.","Reformula y confronta; nunca des tu opinión."],"ej":[["Les deux auteurs reconnaissent que le télétravail fait gagner du temps.","Ambos reconocen que ahorra tiempo."],["Si le premier le juge bénéfique, le second en souligne les risques.","Si el primero lo ve beneficioso, el segundo subraya sus riesgos."],["Le télétravail : progrès ou isolement ?","Título con tensión"]],"ojo":["À mon avis, le télétravail…","L'auteur du premier document estime que…","En la síntesis no se opina."]},"p-resume":{"idea":"Proyecto guiado: resumes en 70 palabras un texto sobre la IA en la universidad. El texto está en el botón «Texte de la leçon» de cada ejercicio.","pasos":["Lee el texto dos veces y busca la tesis.","Escribe una idea por párrafo con tus palabras.","Conserva los conectores (pourtant, donc).","Cuenta: 70 palabras ± 10 %."],"ej":[["Plutôt que d'interdire l'IA, l'université doit apprendre à s'en servir.","En vez de prohibir la IA, la universidad debe enseñar a usarla."],["pourtant → opposition","pourtant → oposición"],["délèguent à la machine l'effort de penser → confient leur réflexion à l'outil","reformulación"]],"ojo":["L'auteur pense que…","(escribe la idea directamente)","Sin nombrar al autor."]},"p-essai":{"idea":"Proyecto guiado: construyes un ensayo en forma de artículo sobre si la IA amenaza a la universidad, pieza por pieza.","pasos":["Identifica el tipo de pregunta (cerrada → plan dialéctico).","Escribe la problemática y el gancho.","Concede y refuta: certes…, mais…","Concluye con apertura y pon un título."],"ej":[["L'IA menace-t-elle l'université ?","¿Amenaza la IA a la universidad?"],["Certes, l'IA facilite la triche, mais elle peut enrichir l'apprentissage.","Es cierto que facilita la trampa, pero puede enriquecer el aprendizaje."],["Reste à savoir si les enseignants en auront les moyens.","Queda por saber si los profesores tendrán los medios."]],"ojo":["L'IA est-elle bien ou pas ?","Dans quelle mesure l'IA menace-t-elle… ?","Una problemática precisa."]},"c12-francophonie":{"idea":"La francofonía son todas las personas y territorios que comparten el francés, no solo Francia y sus excolonias. Con mayúscula, la Francophonie es la institución (OIF).","pasos":["francophonie (minúscula) = los hablantes; Francophonie (mayúscula) = la OIF.","La palabra la inventó Onésime Reclus a finales del siglo XIX.","La institución nace en Niamey el 20 de marzo de 1970 (Día de la Francofonía).","Cinco zonas: Europa, África, Américas, océano Índico y Pacífico."],"ej":[["la Journée internationale de la Francophonie (20 mars)","el Día de la Francofonía (20 de marzo)"],["Le Sénégal est membre de l'OIF.","Senegal es miembro de la OIF."],["Plus de 300 millions de francophones","Más de 300 millones de francófonos"]],"ojo":["La francophonie = la France et ses colonies","La francophonie = tous ceux qui ont le français en partage","Francia es solo una parte."]},"c12-varietes":{"idea":"El francés tiene muchas variedades y ninguna es un error: cada región tiene su propia norma, como el español de Colombia y el de España.","pasos":["Variación geográfica: Bélgica, Suiza, Québec, África.","Bélgica y Suiza: septante (70), nonante (90); huitante (80) en algunos cantones suizos.","Québec: courriel, magasiner (ir de compras), fin de semaine, char (carro).","El registro también varía según la situación."],"ej":[["septante-cinq (Belgique)","setenta y cinco"],["On dîne à midi (Belgique, Québec).","Almorzamos al mediodía."],["un courriel (Québec)","un correo electrónico"]],"ojo":["septante est une faute","septante est une variante régionale","Variación ≠ error."]},"c12-revolution-republique":{"idea":"Los grandes debates franceses de hoy (laicidad, derechos, instituciones) vienen de fechas clave desde la Revolución hasta la Quinta República.","pasos":["1789: toma de la Bastilla y Declaración de los Derechos del Hombre.","1848: abolición definitiva de la esclavitud.","1905: separación de las Iglesias y el Estado (laicidad).","1944: voto de las mujeres; 1958: Quinta República; 1968: Mayo del 68."],"ej":[["« Les hommes naissent et demeurent libres et égaux en droits. »","Art. 1 de la Declaración de 1789"],["la loi de 1905","la ley de separación Iglesia-Estado"],["la Constitution du 4 octobre 1958","la Constitución de la V República"]],"ojo":["L'esclavage est aboli en 1789.","Aboli en 1794, rétabli en 1802, aboli définitivement en 1848.","La Declaración no abolió la esclavitud."]},"c12-decolonisation":{"idea":"La historia colonial explica muchos debates actuales de la francofonía. Las independencias no ocurrieron todas al mismo tiempo.","pasos":["Haití: primera república negra independiente, 1 de enero de 1804.","1960, «año de África»: la mayoría de las colonias subsaharianas se independizan.","Argelia: guerra de 1954 a 1962, acuerdos de Évian.","Negritud (años 1930): Césaire, Senghor, Damas."],"ej":[["En 1960, le Sénégal accède à l'indépendance.","En 1960, Senegal accede a la independencia."],["la guerre d'Algérie (1954-1962)","la guerra de Argelia"],["Cahier d'un retour au pays natal (Césaire, 1939)","obra fundadora de la Negritud"]],"ojo":["L'Algérie devient indépendante en 1960.","L'Algérie devient indépendante en 1962.","Tras una guerra de ocho años."]},"c12-quebec":{"idea":"Québec es uno de los grandes polos de la francofonía. Su historia explica su defensa del francés.","pasos":["1534: Jacques Cartier explora el San Lorenzo.","1608: Samuel de Champlain funda Québec.","1763: tratado de París (Nueva Francia pasa a Inglaterra).","Años 1960: Revolución tranquila; 1977: ley 101 (francés lengua oficial)."],"ej":[["Champlain fonde Québec en 1608.","Champlain funda Québec en 1608."],["à Québec (ville) / au Québec (province)","en la ciudad / en la provincia"],["la loi 101","la ley que protege el francés"]],"ojo":["Cartier fonde Québec en 1534.","Champlain fonde Québec en 1608.","Cartier solo exploró."]},"c12-institutions":{"idea":"La sociedad francesa se organiza alrededor de símbolos y valores republicanos, como la laicidad, y de un sistema educativo propio.","pasos":["Símbolos: lema (Liberté, Égalité, Fraternité), bandera, Marseillaise, Marianne, 14 de julio.","Laicidad = neutralidad del Estado + libertad de conciencia.","Escuela: collège (6e-3e) → lycée (seconde-terminale) → bac.","Grandes écoles: concurso de ingreso, a menudo tras una prépa."],"ej":[["La France est une République laïque.","Francia es una república laica."],["Marianne, symbole de la République","Marianne, símbolo de la República"],["passer le bac","presentar el bachillerato"]],"ojo":["La laïcité interdit les religions.","La laïcité garantit la liberté de conscience.","No prohíbe las religiones."]},"c12-arts":{"idea":"El cine, la canción, el cómic y la gastronomía son referencias culturales que aparecen en conversaciones y documentos del DALF, y van más allá de Francia.","pasos":["1895: primera proyección de los hermanos Lumière.","Nueva Ola (fin de los años 50): Truffaut, Godard.","Brel y Stromae son belgas; Piaf es francesa.","Tintín (Hergé, 1929), Astérix (1959); comida francesa en la UNESCO (2010)."],"ej":[["le cinéma, « septième art »","el cine, «séptimo arte»"],["Stromae est un chanteur belge.","Stromae es un cantante belga."],["la bande dessinée (BD)","el cómic"]],"ojo":["Brel et Stromae sont français.","Brel et Stromae sont belges.","La cultura francófona no es solo francesa."]},"lit-genres-registres":{"idea":"Antes de comentar un texto, identifica su género (la forma) y su registro (el efecto que busca en el lector).","pasos":["Géneros: novela (roman), poesía, teatro, ensayo; relato breve = nouvelle.","Registro trágico = fatalidad; patético = compasión.","Satírico = burla crítica; polémico = ataque directo.","Justifica siempre con indicios del texto."],"ej":[["Maupassant, maître de la nouvelle","Maupassant, maestro del cuento"],["« Ô rage ! ô désespoir ! » → théâtre, registre tragique","teatro, registro trágico"],["un pamphlet polémique","un panfleto polémico"]],"ojo":["une romance (pour « novela »)","un roman","romance es una canción sentimental."]},"lit-figures-style":{"idea":"Las figuras de estilo son recursos del lenguaje. En un comentario siempre se sigue el esquema: cita → recurso → efecto.","pasos":["Comparación: con herramienta (comme, tel). Metáfora: sin herramienta.","Antítesis: oposición entre dos grupos; oxímoron: dentro del mismo grupo.","Anáfora: repetición al inicio; quiasmo: ABBA.","Lítote: decir menos para decir más («Va, je ne te hais point»)."],"ej":[["« La Nature est un temple » → métaphore","sin «comme»: metáfora"],["« cette obscure clarté » → oxymore","«esta oscura claridad»"],["« Va, je ne te hais point » → litote","«No te odio» = te amo"]],"ojo":["« La Nature est un temple » = comparaison","= métaphore","Sin herramienta de comparación."]},"lit-versification-commentaire":{"idea":"Para contar sílabas en la poesía francesa hay reglas propias, sobre todo con la e muda. El alejandrino tiene 12 sílabas partidas en dos mitades.","pasos":["Alejandrino = 12 sílabas, cesura en la mitad (6 // 6).","e muda: se cuenta delante de consonante, se elide delante de vocal y nunca cuenta al final del verso.","Rimas: AABB (seguidas), ABAB (cruzadas), ABBA (abrazadas).","Soneto = 2 cuartetos + 2 tercetos."],"ej":[["Ro-me-l'u-ni-qu'ob-jet (6 sílabas)","la e se elide ante vocal"],["AABB, ABAB, ABBA","tipos de rima"],["citation → procédé → effet","cita → recurso → efecto"]],"ojo":["Contar la e final del verso","La e final nunca cuenta","Ni la e ante vocal."]},"lit-classicisme-lumieres":{"idea":"El siglo XVII es el del clasicismo (reglas, orden, Luis XIV); el XVIII es el de las Luces (razón, tolerancia, crítica del poder).","pasos":["XVII, clasicismo: Corneille, Racine, Molière, La Fontaine.","Regla de las tres unidades: lugar, tiempo, acción.","XVIII, Luces: Voltaire (Candide, 1759), Montesquieu, Rousseau, Diderot.","Montesquieu: separación de poderes; Rousseau: contrato social."],"ej":[["Tartuffe (Molière) dénonce l'hypocrisie religieuse.","Tartufo denuncia la hipocresía religiosa."],["Candide, conte philosophique","Cándido, cuento filosófico"],["De l'esprit des lois (1748)","El espíritu de las leyes"]],"ojo":["Les Lumières = XVIIe siècle","Les Lumières = XVIIIe siècle","El XVII es el clasicismo."]},"lit-romantisme-realisme":{"idea":"El siglo XIX es el gran siglo de la novela: primero el romanticismo (el yo, la emoción), luego el realismo y el naturalismo (la sociedad tal como es).","pasos":["Romanticismo: el yo, la emoción, la libertad; Hugo mezcla lo grotesco y lo sublime.","Realismo: Balzac (La Comédie humaine), Stendhal, Flaubert (Madame Bovary).","Naturalismo: Zola, herencia y medio social (Les Rougon-Macquart).","Maupassant: maestro del cuento."],"ej":[["La Comédie humaine (Balzac)","el conjunto de novelas de Balzac"],["Madame Bovary (1857)","novela realista de Flaubert"],["Germinal (Zola)","novela naturalista"]],"ojo":["Le romantisme = des histoires d'amour","Le romantisme = le moi, l'émotion, la liberté de l'art","Es un movimiento literario."]},"lit-poesie-xixe":{"idea":"Entre Baudelaire y Mallarmé la poesía francesa se vuelve moderna: busca sugerir más que describir.","pasos":["Baudelaire, Les Fleurs du mal (1857): spleen e ideal, correspondencias.","Verlaine: «De la musique avant toute chose».","Rimbaud: «Je est un autre», el poeta vidente.","Simbolismo (Mallarmé): sugerir en vez de nombrar."],"ej":[["Les Fleurs du mal","Las flores del mal"],["« Je est un autre » (Rimbaud)","«Yo es otro»"],["suggérer plutôt que nommer","sugerir en vez de nombrar"]],"ojo":["Verlaine et Rimbaud, poètes romantiques","poètes maudits, sensibilité symboliste","Son de la segunda mitad del XIX."]},"lit-xxe-siecle":{"idea":"El siglo XX cuestiona todas las formas heredadas: el tiempo del relato, el personaje, la lógica.","pasos":["Proust: la memoria involuntaria (la magdalena).","Breton, 1924: surrealismo, sueño, escritura automática.","Sartre: existencialismo; Camus: el absurdo (L'Étranger, 1942).","Nouveau Roman (Butor, Robbe-Grillet); Annie Ernaux, Nobel 2022."],"ej":[["Dans L'Étranger, Meursault raconte à la première personne.","En El extranjero, Meursault narra en primera persona."],["la madeleine de Proust","la magdalena de Proust"],["Sartre refuse le prix Nobel en 1964.","Sartre rechaza el Nobel en 1964."]],"ojo":["Camus, philosophe existentialiste","Camus, philosophie de l'absurde","Camus rechazó esa etiqueta."]},"lit-francophonies":{"idea":"La literatura en francés no es solo de Francia: África, el Magreb, las Antillas y Québec tienen grandes autores y movimientos propios.","pasos":["Negritud: Césaire, Senghor, Damas; París, años 1930.","Magreb: Kateb Yacine, Assia Djebar.","Antillas y Haití: Glissant, Maryse Condé, Laferrière.","África subsahariana: Hampâté Bâ (tradición oral), Kourouma, Mariama Bâ."],"ej":[["Une si longue lettre (Mariama Bâ, 1979), roman épistolaire","novela epistolar"],["Hampâté Bâ défend la tradition orale.","Hampâté Bâ defiende la tradición oral."],["la créolisation (Glissant)","la criollización"]],"ojo":["La Négritude est née à Dakar.","La Négritude est née à Paris.","Entre estudiantes de las colonias."]},"f-e":{"idea":"La é (aguda) es una e cerrada; la è (grave) es abierta y va antes de una sílaba final muda. Delante de consonante doble o x, la e no lleva tilde.","pasos":["é: al final de sílaba: é-lè-ve, ré-su-mé.","è: antes de sílaba final muda: pro-blè-me, siè-cle.","Sin tilde delante de consonante doble o x: elle, effet, exemple.","Truco: préférer → je préfère."],"ej":[["le problème","el problema"],["la société","la sociedad"],["un exemple","un ejemplo (sin tilde)"]],"ojo":["éxemple, éffet","exemple, effet","Sin tilde ante x o consonante doble."]},"f-circ":{"idea":"El acento circunflejo (^) marca casi siempre una s que desapareció y que el español conserva. Es un truco muy útil.","pasos":["Busca la palabra española con s: fiesta → fête, costa → côte.","isla → île, bestia → bête, castillo → château.","También distingue palabras: sûr / sur, mûr / mur, dû / du.","hospital → hôpital, maestro → maître."],"ej":[["la fête","la fiesta"],["la forêt","el bosque (forest)"],["l'hôpital","el hospital"]],"ojo":["la fete, l'hopital","la fête, l'hôpital","La s perdida se vuelve ^."]},"f-ced":{"idea":"La cedilla (ç) hace sonar la c como [s] delante de a, o, u. Delante de e e i no hace falta.","pasos":["ça, garçon, reçu: ç delante de a, o, u.","ceci, merci: sin cedilla delante de e, i.","Verbos en -cer: nous commençons, je commençais.","recevoir: il a reçu, ils reçoivent."],"ej":[["le garçon","el muchacho"],["nous commençons","empezamos"],["J'ai reçu ton message.","Recibí tu mensaje."]],"ojo":["nous commencons","nous commençons","Sin cedilla se leería [k]."]},"f-trema":{"idea":"La diéresis (¨) indica que la vocal se pronuncia aparte de la anterior, como en «pingüino».","pasos":["naïf = na-if (sin ¨ sonaría como en lait).","maïs = ma-is; Noël = No-ël.","ambiguë lleva la diéresis sobre la e."],"ej":[["naïf","ingenuo"],["le maïs","el maíz"],["Noël","Navidad"]],"ojo":["mais (para «maíz»)","maïs","mais = pero."]},"f-lig":{"idea":"La o y la e se escriben unidas (œ) en palabras muy comunes. Separarlas se considera una falta en escritura cuidada.","pasos":["œ: cœur, sœur, œuvre, vœu, bœuf, œil.","æ es rara: ex æquo.","En el ejercicio, toca la o y elige œ."],"ej":[["ma sœur","mi hermana"],["le cœur","el corazón"],["une œuvre","una obra"]],"ojo":["coeur, soeur","cœur, sœur","Letras unidas."]},"f-sans":{"idea":"Muchas palabras que en español llevan tilde no llevan ningún acento en francés. A veces la respuesta correcta es no tocar nada.","pasos":["fácil → facile, música → musique, política → politique.","acción → action, técnica → technique.","Nunca tilde en e delante de consonante doble o x: effet, examen."],"ej":[["facile","fácil"],["la musique","la música"],["la politique","la política"]],"ojo":["facíle, músique","facile, musique","No copies la tilde española."]},"f-sens":{"idea":"En francés un acento puede cambiar por completo el sentido de una palabra. Hay trucos para saber cuál usar.","pasos":["a (verbo avoir) / à (preposición): si puedes decir avait, es a.","ou (o) / où (dónde): si puedes decir ou bien, es ou.","sur (sobre) / sûr (seguro); du (del) / dû (de devoir).","la (artículo) / là (allí); des / dès (desde)."],"ej":[["Il a un livre à la main.","Tiene un libro en la mano."],["Où vas-tu ? Au cinéma ou au parc ?","¿Adónde vas? ¿Al cine o al parque?"],["Tu es sûr ? C'est sur la table.","¿Estás seguro? Está sobre la mesa."]],"ojo":["Il à faim.","Il a faim.","a = verbo (avait)."]}};